package io.github.tavim26.onlinestore.dao;

import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

final class JdbcUtils {

    private JdbcUtils() {
    }

    /** Returns the AUTO_INCREMENT id generated by the last INSERT. */
    static int generatedId(PreparedStatement statement) throws SQLException {
        try (ResultSet keys = statement.getGeneratedKeys()) {
            if (!keys.next()) {
                throw new SQLException("No generated key was returned.");
            }
            return keys.getInt(1);
        }
    }
}